def transform(grid):
    h = next(r for r, row in enumerate(grid) if all(x == 3 for x in row))
    w = next(c for c in range(len(grid[0])) if all(row[c] == 3 for row in grid))
    return [[3 if r == h or c == w else (4 if max(abs(r-h), abs(c-w)) % 2 == 0 else 0)
             for c in range(len(grid[0]))] for r in range(len(grid))]
